srcDoc.css:
:root {
  --ink:#17334b;
  --muted:#62778a;
  --blue:#225cdb;
  --teal:#0c786e;
  --line:#dce5ee;
  --bg:#f3f7fb;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 15px/1.5 "Segoe UI", Arial, sans-serif;
}

button, input, select, textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible {
  outline: 3px solid #eaa62f;
  outline-offset: 3px;
}

button {
  transition: background 0.15s;
}

button:hover {
  filter: brightness(0.96);
}

.shell {
  min-height: 950px;
}

.top {
  background: #fff;
  border-bottom: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 5%;
  gap: 24px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 23px;
  letter-spacing: -1px;
  font-weight: 800;
  white-space: nowrap;
}

.mark {
  background: var(--blue);
  color: white;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  font-size: 24px;
}

.brand small {
  display: block;
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 1.7px;
  text-transform: uppercase;
  font-weight: 600;
  margin-top: -4px;
}

.nav {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.nav button {
  background: transparent;
  border: 0;
  color: var(--muted);
  padding: 10px 14px;
  font-weight: 600;
  border-radius: 8px;
}

.nav button.active {
  background: #eaf1ff;
  color: var(--blue);
}

.btn {
  border: 1px solid var(--line);
  border-radius: 9px;
  padding: 11px 18px;
  background: white;
  color: var(--ink);
  font-weight: 650;
  display: inline-flex;
  gap: 8px;
  align-items: center;
  justify-content: center;
}

.btn.primary {
  background: var(--blue);
  border-color: var(--blue);
  color: white;
}

.btn.teal {
  background: var(--teal);
  border-color: var(--teal);
  color: white;
}

.btn.small {
  padding: 7px 12px;
  font-size: 13px;
}

.demo {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  background: #eaf1ff;
  color: #36557c;
  padding: 8px 5%;
  font-size: 12px;
}

.demo button {
  border: 0;
  background: transparent;
  color: #214eac;
  text-decoration: underline;
  font-size: 12px;
}

.wrap {
  max-width: 1220px;
  margin: auto;
  padding: 32px;
}

.hero {
  background: #e3edf9;
  border-radius: 20px;
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  align-items: center;
  padding: 38px 42px;
  gap: 28px;
  overflow: hidden;
}

.eyebrow {
  color: var(--teal);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.8px;
  text-transform: uppercase;
}

.hero h1 {
  font-size: 42px;
  line-height: 1.12;
  letter-spacing: -1.8px;
  margin: 12px 0 16px;
  max-width: 570px;
  font-weight: 750;
}

.hero p {
  color: #536e86;
  max-width: 440px;
  margin: 0;
  font-size: 15px;
}

.route-art {
  position: relative;
  height: 155px;
  display: flex;
  align-items: center;
  justify-content: space-around;
}

.route-art:before {
  content: "";
  position: absolute;
  left: 20%;
  right: 20%;
  top: 69px;
  height: 6px;
  background: #739edc;
  border-radius: 20px;
}

.stop {
  position: relative;
  text-align: center;
  z-index: 1;
}

.stop i {
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  margin: auto auto 12px;
  background: #fff;
  border: 5px solid #b6cff0;
  border-radius: 50%;
  font-size: 25px;
  font-style: normal;
}

.stop strong {
  font-size: 13px;
}

.stop small {
  display: block;
  color: var(--muted);
  font-size: 11px;
}

.car {
  position: relative;
  background: var(--blue);
  color: white;
  padding: 10px 15px;
  border-radius: 12px;
  font-size: 22px;
  box-shadow: 0 5px 0 #b6cff0;
  transform: translateY(-13px);
}

.search {
  background: white;
  margin: 22px 0 28px;
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: 0 5px 16px rgba(23, 51, 75, 0.0196078431);
  display: grid;
  grid-template-columns: 1fr 1fr 0.85fr 0.7fr auto;
  gap: 14px;
  align-items: end;
}

.field label {
  display: block;
  font-size: 12px;
  font-weight: 700;
  margin: 0 0 7px;
}

.field input, .field select, .field textarea {
  width: 100%;
  background: white;
  border: 1px solid #cad7e4;
  border-radius: 8px;
  color: var(--ink);
  padding: 11px 12px;
  min-height: 44px;
}

.field input::placeholder, .field textarea::placeholder {
  color: #8293a4;
}

.field textarea {
  resize: none;
  min-height: 110px;
}

.field .help {
  font-size: 12px;
  color: var(--muted);
  margin: 6px 0 0;
}

.heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin: 25px 0 18px;
}

.heading h2 {
  margin: 0;
  font-size: 22px;
  letter-spacing: -0.6px;
}

.heading p, .sub {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: 24px;
  align-items: start;
}

.cards {
  display: grid;
  gap: 14px;
}

.card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 13px;
  padding: 24px;
}

.trip {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 20px;
}

.trip-route {
  display: grid;
  grid-template-columns: 55px 16px 1fr;
  gap: 2px 12px;
  align-items: center;
}

.time {
  font-weight: 750;
  font-size: 15px;
}

.dot {
  width: 11px;
  height: 11px;
  border: 3px solid var(--blue);
  border-radius: 50%;
  margin: auto;
}

.dot.end {
  background: var(--blue);
}

.path {
  height: 25px;
  border-left: 2px solid #b8cce7;
  margin: auto;
}

.place {
  font-size: 16px;
  font-weight: 700;
}

.place small {
  display: block;
  color: var(--muted);
  font-size: 12px;
  font-weight: 400;
}

.duration {
  color: var(--muted);
  font-size: 11px;
}

.fare {
  text-align: right;
}

.fare strong {
  font-size: 27px;
  letter-spacing: -1px;
}

.fare small {
  display: block;
  color: var(--muted);
  font-size: 12px;
}

.trip-footer {
  grid-column: 1/-1;
  border-top: 1px solid #edf1f5;
  padding-top: 15px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}

.person {
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 13px;
}

.avatar {
  display: grid;
  place-items: center;
  background: #e6f2f0;
  color: var(--teal);
  width: 35px;
  height: 35px;
  border-radius: 50%;
  font-size: 12px;
  font-weight: 750;
}

.tag {
  display: inline-block;
  background: #e8f5ef;
  color: #19664d;
  padding: 4px 8px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 650;
}

.note {
  color: var(--muted);
  font-size: 12px;
}

.aside {
  background: #e9f3f1;
  border: 1px solid #d0e6df;
  border-radius: 14px;
  padding: 24px;
}

.aside h3 {
  font-size: 19px;
  line-height: 1.3;
  margin: 12px 0;
}

.aside p {
  font-size: 13px;
  color: #506e6a;
}

.aside .btn {
  width: 100%;
  margin-top: 15px;
}

.aside hr {
  border: 0;
  border-top: 1px solid #cce0da;
  margin: 24px 0;
}

.empty {
  text-align: center;
  padding: 48px 25px;
  background: white;
  border: 1px dashed #cbd9e6;
  border-radius: 13px;
}

.empty h3 {
  margin: 14px 0 5px;
}

.empty p {
  color: var(--muted);
  font-size: 14px;
  max-width: 430px;
  margin: 0 auto 20px;
}

.empty-icon {
  display: inline-grid;
  place-items: center;
  width: 60px;
  height: 60px;
  border-radius: 18px;
  background: #eaf1ff;
  font-size: 26px;
}

.form-card {
  max-width: 780px;
  margin: 24px auto;
  background: white;
  border: 1px solid var(--line);
  border-radius: 15px;
  padding: 30px;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.span {
  grid-column: 1/-1;
}

.actions {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
}

.notice {
  padding: 12px 15px;
  background: #edf3fc;
  border-radius: 8px;
  color: #456283;
  font-size: 12px;
  margin-top: 20px;
}

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}

.stat {
  background: white;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 22px;
}

.stat strong {
  display: block;
  font-size: 30px;
  color: var(--blue);
}

.stat span {
  color: var(--muted);
  font-size: 13px;
}

.tabs {
  display: flex;
  gap: 6px;
  margin: 25px 0 18px;
  border-bottom: 1px solid var(--line);
}

.tabs button {
  padding: 12px 18px;
  border: 0;
  background: transparent;
  color: var(--muted);
  font-weight: 600;
  border-bottom: 3px solid transparent;
}

.tabs button.active {
  border-color: var(--blue);
  color: var(--blue);
}

.messages {
  display: grid;
  grid-template-columns: 280px 1fr;
  min-height: 420px;
  overflow: hidden;
  background: white;
  border: 1px solid var(--line);
  border-radius: 14px;
}

.inbox {
  border-right: 1px solid var(--line);
  padding: 20px;
}

.chat {
  padding: 25px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.bubble {
  background: #eef3fa;
  border-radius: 12px 12px 12px 0;
  padding: 13px 17px;
  max-width: 80%;
  font-size: 14px;
}

.bubble.mine {
  align-self: flex-end;
  background: #e3f0ee;
  border-radius: 12px 12px 0 12px;
}

.chat-form {
  display: flex;
  gap: 10px;
  margin-top: auto;
}

.chat-form input {
  flex: 1;
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
}

.footer {
  margin: 32px 0 0;
  padding: 20px 0;
  border-top: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font-size: 11px;
  gap: 20px;
}

.error {
  font-size: 13px;
  color: #ac302e;
  margin: 12px 0;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(23, 51, 75, 0.4);
  display: grid;
  place-items: center;
  padding: 20px;
  z-index: 100;
}

.modal {
  background: #fff;
  padding: 30px;
  border-radius: 18px;
  max-width: 540px;
  width: 100%;
  max-height: 90vh;
  overflow: auto;
}

.modal header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.modal h2 {
  margin: 0;
  font-size: 23px;
}

.modal .field {
  margin: 15px 0;
}

.close {
  background: transparent;
  border: 0;
  font-size: 25px;
  color: var(--muted);
}

.check {
  width: 50px;
  height: 50px;
  background: #e1f1eb;
  color: var(--teal);
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 24px;
}

.readonly {
  background: #f4f7fb;
  padding: 12px;
  border-radius: 8px;
}

.pill {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--teal);
  font-size: 12px;
}

.pill:before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--teal);
}

@media (min-width: 1600px) {
  .wrap {
    max-width: 1400px;
  }
  .hero {
    padding: 45px 55px;
  }
}
@media (max-width: 900px) {
  .top {
    flex-wrap: wrap;
    padding: 15px 24px;
  }
  .nav {
    order: 3;
    width: 100%;
    justify-content: center;
  }
  .search {
    grid-template-columns: 1fr 1fr;
  }
  .search .btn {
    grid-column: 1/-1;
  }
  .columns {
    grid-template-columns: 1fr;
  }
  .aside {
    display: none;
  }
  .hero {
    grid-template-columns: 1fr;
    padding: 28px;
  }
  .route-art {
    display: none;
  }
  .hero h1 {
    font-size: 35px;
  }
  .wrap {
    padding: 24px;
  }
  .messages {
    grid-template-columns: 220px 1fr;
  }
}
@media (max-width: 540px) {
  .wrap {
    padding: 16px;
  }
  .hero h1 {
    font-size: 30px;
  }
  .hero {
    padding: 24px;
  }
  .top {
    padding: 14px 16px;
    gap: 10px;
  }
  .brand {
    font-size: 21px;
  }
  .nav {
    gap: 0;
    justify-content: space-between;
  }
  .nav button {
    font-size: 12px;
    padding: 9px 7px;
  }
  .demo {
    padding: 8px 16px;
    align-items: start;
  }
  .demo span {
    max-width: 240px;
  }
  .search, .form-grid {
    grid-template-columns: 1fr;
  }
  .search {
    padding: 16px;
  }
  .search .btn, .span {
    grid-column: auto;
  }
  .trip {
    gap: 14px;
    padding: 18px;
  }
  .trip-route {
    grid-template-columns: 40px 12px 1fr;
    gap: 2px 8px;
  }
  .place {
    font-size: 14px;
  }
  .fare strong {
    font-size: 22px;
  }
  .trip-footer {
    flex-wrap: wrap;
  }
  .trip-footer .btn {
    width: 100%;
  }
  .stats {
    gap: 8px;
  }
  .stat {
    padding: 14px;
  }
  .stat strong {
    font-size: 24px;
  }
  .stat span {
    font-size: 11px;
  }
  .heading {
    align-items: start;
  }
  .heading h2 {
    font-size: 20px;
  }
  .form-card {
    padding: 20px;
  }
  .messages {
    grid-template-columns: 1fr;
  }
  .inbox {
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }
  .chat {
    padding: 18px;
  }
  .footer {
    flex-direction: column;
    gap: 6px;
  }
  .actions {
    flex-wrap: wrap;
  }
}
@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}

