const examples=[{id:1,name:"Camille",initials:"CM",from:"Rezé",point:"Place du 8 Mai",to:"Campus ESGI Nantes",arrival:"Entrée du campus",time:"08:00",end:"08:25",price:"2,50",seats:3},{id:2,name:"Alex",initials:"AL",from:"Saint-Herblain",point:"Arrêt Marcel Paul",to:"Campus ESGI Nantes",arrival:"Entrée du campus",time:"08:10",end:"08:40",price:"3,00",seats:2},{id:3,name:"Lou",initials:"LO",from:"Nantes centre",point:"Place Commerce",to:"Campus ESGI Nantes",arrival:"Entrée du campus",time:"08:20",end:"08:35",price:"2,00",seats:1}];
function Field({label,id,children,help}){return <div className="field"><label htmlFor={id}>{label}</label>{children}{help&&<p className="help">{help}</p>}</div>}
function App(){
const [page,setPage]=useState("search"),[demo,setDemo]=useState(true),[from,setFrom]=useState(""),[to,setTo]=useState(""),[date,setDate]=useState(""),[places,setPlaces]=useState("1"),[query,setQuery]=useState(null),[modal,setModal]=useState(null),[trip,setTrip]=useState(null),[tab,setTab]=useState("reservations"),[reserved,setReserved]=useState([]),[drafts,setDrafts]=useState([]),[chat,setChat]=useState([]),[message,setMessage]=useState(""),[error,setError]=useState(""),[loginMode,setLoginMode]=useState(false);
