return <div className="shell"><header className="top"><div className="brand"><span className="mark" aria-hidden="true">↗</span><div>Campus<span style={{color:"var(--blue)"}}>Covoit</span><small>Le campus, ensemble.</small></div></div><nav className="nav" aria-label="Navigation principale">{[["search","Rechercher"],["dashboard","Mes trajets"],["messages","Messages"],["profile","Mon profil"]].map(([id,label])=><button key={id} className={page===id?"active":""} aria-current={page===id?"page":undefined} onClick={()=>go(id)}>{label}</button>)}</nav><button className="btn primary" onClick={()=>go("publish")}>+ Proposer un trajet</button></header><div className="demo"><span><strong>Prototype visuel</strong> · {demo?"Données d'exemple · aucune action réelle ni paiement.":"Aperçu sans exemples · aucune connexion aux données."}</span><button onClick={()=>{setDemo(!demo);setQuery(null);}}>{demo?"Masquer les exemples":"Afficher les exemples"}</button></div><main className="wrap" id="main" tabIndex="-1">
{page==="search"&&<><section className="hero"><div><span className="eyebrow">Covoiturage étudiant · Nantes</span><h1>Un même campus.<br/>Un trajet à partager.</h1><p>Trouvez votre covoiturage entre chez vous et les cours. Moins de frais, plus de rencontres.</p></div><div className="route-art" aria-hidden="true"><div className="stop"><i>⌂</i><strong>Chez vous</strong><small>Votre point de départ</small></div><div className="car">↗</div><div className="stop"><i>⚑</i><strong>Le campus</strong><small>On y va ensemble</small></div></div></section><form className="search" noValidate onSubmit={e=>{e.preventDefault();setQuery({from,to,date,places});}}><Field label="Départ" id="search-from"><input id="search-from" placeholder="Ville ou quartier" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="Arrivée" id="search-to"><input id="search-to" placeholder="Campus ESGI Nantes" value={to} onChange={e=>setTo(e.target.value)}/></Field><Field label="Date de départ" id="search-date"><input type="date" id="search-date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="Passagers" id="search-seats"><select id="search-seats" value={places} onChange={e=>setPlaces(e.target.value)}>{[1,2,3,4].map(n=><option key={n} value={n}>{n} personne{n>1?"s":""}</option>)}</select></Field><button className="btn primary" type="submit">Rechercher →</button></form><div className="columns"><section><div className="heading"><div><h2>{query?"Résultats de recherche":"Trajets vers le campus"}</h2><p>{demo?filtered.length+" trajet(s) d'exemple · horaires et tarifs fictifs":"Aucun trajet chargé"}</p></div>{(from||to||date||query)&&<button className="btn small" onClick={()=>{setFrom("");setTo("");setDate("");setPlaces("1");setQuery(null);}}>Effacer les filtres</button>}</div>{query?.date&&<p className="notice">Les exemples illustrent un trajet type ; la date ne filtre pas de disponibilités réelles.</p>}<div className="cards">{filtered.length?filtered.map(t=>card(t)):empty("Aucun trajet pour le moment",demo?"Essayez une autre ville ou effacez les filtres pour voir tous les exemples.":"Les trajets apparaîtront ici une fois les données connectées.",demo?"Effacer les filtres":"Voir les exemples",()=>{setDemo(true);setQuery(null);setFrom("");setTo("");})}</div></section><aside className="aside"><span className="eyebrow">Côté conducteur</span><h3>Une place libre ?<br/>Partagez votre trajet.</h3><p>Vous faites déjà le trajet jusqu'au campus. Proposez les places disponibles aux autres étudiants.</p><button className="btn teal" onClick={()=>go("publish")}>Proposer un trajet →</button><hr/><strong style={{fontSize:14}}>Chacun participe, simplement.</strong><p>La participation aux frais se règle directement entre conducteur et passager.</p><div className="pill">Aucun paiement dans l'application</div></aside></div></>}
{page==="publish"&&<><div className="heading"><div><span className="eyebrow">Espace conducteur</span><h2>Proposer un trajet</h2><p>Indiquez votre itinéraire et les places que vous souhaitez partager.</p></div><button className="btn small" onClick={()=>go("search")}>← Rechercher</button></div><form className="form-card" noValidate onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(!String(f.get("title")).trim()||!String(f.get("start")).trim()||!String(f.get("end")).trim()||!f.get("date")||!f.get("time")){setError("Renseignez le titre, le départ, l'arrivée, la date et l'heure.");e.currentTarget.querySelector("input")?.focus();return;}if(String(f.get("start")).trim().toLowerCase()===String(f.get("end")).trim().toLowerCase()){setError("Choisissez une arrivée différente du départ.");return;}setDrafts([...drafts,{title:f.get("title"),start:f.get("start"),end:f.get("end"),date:f.get("date"),time:f.get("time"),seats:f.get("seats"),price:f.get("price")}]);setError("");open("published");}}><div className="form-grid"><div className="span"><Field id="pub-title" label="Nom du trajet"><input id="pub-title" name="title" placeholder="Ex. Matin · Rezé → Campus ESGI" maxLength="120" required/></Field></div><Field id="pub-start" label="Point de départ"><input id="pub-start" name="start" placeholder="Ville, quartier ou lieu de rendez-vous" required/></Field><Field id="pub-end" label="Point d'arrivée"><input id="pub-end" name="end" placeholder="Campus ou lieu d'arrivée" required/></Field><Field id="pub-date" label="Date de départ"><input id="pub-date" name="date" type="date" required/></Field><Field id="pub-time" label="Heure de départ"><input id="pub-time" name="time" type="time" required/></Field><Field id="pub-seats" label="Places proposées"><select id="pub-seats" name="seats">{[1,2,3,4].map(n=><option key={n} value={n}>{n} place{n>1?"s":""}</option>)}</select></Field><Field id="pub-price" label="Participation par personne (€)" help="À régler directement entre étudiants."><input id="pub-price" name="price" type="number" min="0" step="0.5" defaultValue="2.50"/></Field></div><p className="notice">Aperçu : le trajet sera ajouté uniquement à cette session de démonstration.</p>{error&&<p className="error" role="alert">{error}</p>}<div className="actions"><button type="button" className="btn" onClick={()=>go("search")}>Retour à la recherche</button><button type="submit" className="btn primary">Prévisualiser la publication →</button></div></form></>}
{page==="dashboard"&&<><div className="heading"><div><span className="eyebrow">Votre tableau de bord</span><h2>Mes trajets</h2><p>Retrouvez vos réservations et les trajets que vous proposez.</p></div><button className="btn primary" onClick={()=>go("publish")}>+ Proposer</button></div><div className="stats"><div className="stat"><strong>{reserved.length}</strong><span>Réservations simulées</span></div><div className="stat"><strong>{drafts.length}</strong><span>Publications simulées</span></div><div className="stat"><strong>{chat.length}</strong><span>Messages simulés</span></div></div><div className="tabs" role="tablist" aria-label="Mes trajets">{[["reservations","Mes réservations"],["published","Mes publications"]].map(([id,label])=><button role="tab" aria-selected={tab===id} key={id} className={tab===id?"active":""} onClick={()=>setTab(id)}>{label}</button>)}</div><div className="cards">{tab==="reservations"?(reserved.length?reserved.map(t=>card(t,true)):empty("Votre prochain trajet commence ici","Recherchez un trajet puis testez la réservation d'une place.","Trouver un trajet",()=>go("search"))):(drafts.length?drafts.map((d,i)=><article className="card" key={i}><span className="tag">Publication simulée</span><h3>{d.title}</h3><p>{d.start} → {d.end}</p><p className="sub">{d.date} · {d.time} · {d.seats} place(s) · {d.price} € / personne</p></article>):empty("Vous n'avez pas encore proposé de trajet","Vous allez au campus en voiture ? Partagez votre itinéraire.","Proposer un trajet",()=>go("publish")))}</div></>}
{page==="messages"&&<><div className="heading"><div><span className="eyebrow">Avant de prendre la route</span><h2>Messages</h2><p>Échangez sur le point de rendez-vous et les détails du trajet.</p></div></div>{!demo?empty("Aucune conversation","Les échanges apparaîtront ici après la connexion de la messagerie.","Voir un exemple",()=>setDemo(true)):<section className="messages"><aside className="inbox"><div className="person"><span className="avatar">CM</span><div><strong>Camille</strong><div className="note">Rezé → Campus ESGI</div></div></div><p className="notice">Conversation d'exemple</p></aside><div className="chat"><strong>Votre point de rendez-vous</strong><div className="bubble">Bonjour ! Le départ se fait place du 8 Mai à Rezé. Ça vous convient ?<div className="note">Message fictif</div></div>{chat.map((m,i)=><div className="bubble mine" key={i}>{m}<div className="note">Simulation · non envoyé</div></div>)}<form className="chat-form" noValidate onSubmit={e=>{e.preventDefault();if(!message.trim())return;setChat([...chat,message.trim()]);setMessage("");}}><label htmlFor="chat-message" style={{position:"absolute",width:1,height:1,overflow:"hidden"}}>Votre message</label><input id="chat-message" placeholder="Écrire un message d'exemple…" value={message} maxLength="1000" onChange={e=>setMessage(e.target.value)}/><button className="btn primary" disabled={!message.trim()}>Simuler l'envoi</button></form></div></section>}</>}
{page==="profile"&&<><div className="heading"><div><span className="eyebrow">Votre espace étudiant</span><h2>Mon profil</h2><p>Vos informations pour organiser vos covoiturages.</p></div></div><div className="form-card"><div className="person"><span className="avatar" style={{width:50,height:50,fontSize:18}}>?</span><div><h3 style={{margin:0}}>Bienvenue sur CampusCovoit</h3><span className="sub">Connectez-vous pour retrouver votre profil.</span></div></div><div className="form-grid" style={{marginTop:28}}><Field id="profile-name" label="Nom"><input id="profile-name" placeholder="Votre nom" disabled/></Field><Field id="profile-school" label="École"><input id="profile-school" placeholder="Votre établissement" disabled/></Field><div className="span"><Field id="profile-start" label="Lieu de départ habituel"><input id="profile-start" placeholder="Votre ville ou quartier" disabled/></Field></div></div><div className="actions"><button className="btn primary" onClick={()=>{setLoginMode(false);open("auth");}}>Voir l'écran de connexion →</button></div></div></>}
<footer className="footer"><span><strong>CampusCovoit</strong> · Le covoiturage entre étudiants, à Nantes.</span><span>Prototype visuel · aucune donnée réelle enregistrée</span></footer></main>
{modal&&<div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)close();}} onKeyDown={e=>{if(e.key==="Escape")close();if(e.key==="Tab"){const el=e.currentTarget.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled])');if(!el.length)return;const first=el[0],last=el[el.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><h2 id="dialog-title">{({detail:"Votre trajet",booking:"Votre réservation",reserved:"Réservation simulée",published:"Aperçu de publication",auth:loginMode?"Créer mon compte":"Se connecter",authinfo:"Connexion non activée"})[modal]}</h2><button className="close" aria-label="Fermer la fenêtre" onClick={close} autoFocus>×</button></header>{(modal==="detail"||modal==="booking")&&trip&&<><div className="readonly"><strong>{trip.from} → {trip.to}</strong><p>{trip.time} → {trip.end} · {trip.seats} place(s)</p><p>{trip.point} · {trip.arrival}</p></div><div className="person" style={{marginTop:20}}><span className="avatar">{trip.initials}</span><strong>{trip.name} · étudiant</strong></div><p><strong>{trip.price} €</strong> par personne · règlement entre étudiants.</p><p className="notice">Trajet fictif pour tester l'interface. Aucune place réelle n'est réservée.</p><div className="actions"><button className="btn" onClick={()=>{close();go("messages");}}>Contacter</button>{modal==="detail"?<button className="btn primary" disabled={reserved.some(r=>r.id===trip.id)} onClick={()=>{setReserved([...reserved,trip]);setModal("reserved");}}>{reserved.some(r=>r.id===trip.id)?"Déjà simulée":"Simuler la réservation"}</button>:<button className="btn" onClick={()=>{setReserved(reserved.filter(r=>r.id!==trip.id));close();}}>Retirer la simulation</button>}</div></>}{(modal==="reserve